_000747={category="防御",desc="减伤70%，应对攻击：敌方失去3能量。",desc_notes={1016},element="幽系",energy=2,flavor="为报答学长的照顾，今天在他的炼金药剂里面加了一些汽水儿。",game_id=7170150,icon="Skill_705001.png",name="报复"},skill_000748={category="攻击",damage_class="魔攻",desc="对敌方精灵造成魔法伤害。",element="幽系",energy=2,flavor="做了个噩梦，老师说如果我如果下次再上课睡觉的话，就让我的魔力之源永远不能回复魔力。",game_id=7170160,icon="Skill_705002.png",name="恐吓",power=80},skill_000749={category="攻击",damage_class="魔攻",desc="对敌方精灵造成魔法伤害。",element="幽系",energy=5,game_id=7170170,icon="Skill_705004.png",name="幽灵爆发",power=140},skill_000750={category="攻击",damage_class="物攻",desc="对敌方精灵造成物理伤害。",element="幽系",energy=0,flavor="魔法学院传闻有一间废弃的教室，误入的洛克会看到黑板上突然出现了自己的名字，不打扫完卫生没法离开这间教室。",game_id=7170190,icon="Skill_116013.png",name="诡刺",power=40},skill_000751={category="攻击",damage_class="物攻",desc="对敌方精灵造成物理伤害。",element="幽系",energy=1,game_id=7170200,icon="Skill_116014.png",name="幻象",power=60},skill_000752={category="攻击",damage_class="魔攻",desc="造成魔伤，5连击。",element="幽系",energy=4,flavor="铃铛幽灵从不发声。",game_id=7170210,icon="Skill_116015.png",name="午夜噪音",power=20},skill_000753={category="攻击",damage_class="魔攻",desc="对敌方精灵造成魔法伤害。",element="幽系",energy=3,game_id=7170220,icon="Skill_116016.png",name="灵媒",power=100},skill_000754={category="攻击",damage_class="魔攻",desc="造成魔伤，3连击，若敌方本回合更换精灵，本次技能连击数翻倍。",element="幽系",energy=3,flavor="如果在凌晨两点的时候，看到魔法学院图书馆里有光，千万不要进去。",game_id=7170230,icon="Skill_116017.png",name="灵光",power=25},skill_000755={category="状态",desc="自己获得魔攻+90%，若敌方本回合更换精灵，自己获得速度+70。",element="幽系",energy=2,flavor="昨天半夜我们俩摸黑背完咒语课考试范围，隔天发现学长给画的考试范围全是错的。",game_id=7170240,icon="Skill_116018.png",name="嘲弄"},skill_000756={category="状态",desc="偷取敌方3能量。",element="幽系",energy=1,flavor="真的有鬼，月圆夜的时候，魔法学院2楼厕所的卫生纸会全部消失，太可怕了。",game_id=7170250,icon="Skill_116019.png",name="勾魂"},skill_000757={category="防御",desc="减伤80%，应对攻击：自己获得魔防+70%。",desc_notes={1016},element="幽系",energy=2,flavor="\"传闻误入灵魂之河的洛克，会短暂地失去和肉体的链接，如果能及时回来，会拥有一段被自己遗忘的记忆。”",game_id=7170260,icon="Skill_116020.png",name="虚化"},skill_000758={category="状态",desc